// Magellan Lite's source, run in the browser by Try it: written by demo/build_site.py -- do not edit by hand
window.MAGELLAN_ENGINE = {"version": "0.2.0", "files": {"magellan_lite/__init__.py": "\"\"\"Magellan Lite: what a change touched, and the checklist of what it could break.\"\"\"\n\n__version__ = \"0.2.0\"\n", "magellan_lite/defs.py": "\"\"\"The map: every function, method, class and constant in a snapshot, from its syntax tree.\n\nEach definition gets a stable name (``pkg.mod.Class.method``, no line numbers) and hashes of\nwhat it promises and what it does, so comparing two versions finds real changes: moving code,\nreformatting it, editing a docstring or switching line endings changes nothing.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport hashlib\nfrom dataclasses import dataclass\n\nfrom magellan_lite.source import Snapshot, module_name\n\nCALLABLE_KINDS = (\"function\", \"method\")\n\n\n@dataclass(frozen=True)\nclass Params:\n    \"\"\"What a function accepts, to check a call site against it.\"\"\"\n    positional: tuple[str, ...]          # positional parameters, in order (self included)\n    defaults: int                        # how many of the last positional ones have defaults\n    positional_only: int                 # how many lead the list before a `/`\n    varargs: bool                        # *args\n    keyword_only: tuple[str, ...]\n    keyword_required: tuple[str, ...]    # keyword-only parameters without a default\n    varkw: bool                          # **kwargs\n    binds_first: bool                    # a method (not a staticmethod): `self` is passed for you\n\n    def bound(self) -> \"Params\":\n        \"\"\"As seen through ``obj.method(...)``: the first parameter is filled already.\"\"\"\n        if not self.binds_first or not self.positional:\n            return self\n        return Params(self.positional[1:], min(self.defaults, len(self.positional) - 1),\n                      max(self.positional_only - 1, 0), self.varargs, self.keyword_only,\n                      self.keyword_required, self.varkw, False)\n\n    def problems(self, n_positional: int, keywords: tuple[str, ...]) -> list[str]:\n        \"\"\"Why a call with these arguments raises TypeError; empty when it fits.\"\"\"\n        out: list[str] = []\n        if not self.varargs and n_positional > len(self.positional):\n            out.append(f\"takes at most {len(self.positional)} positional argument(s), the call \"\n                       f\"passes {n_positional}\")\n        required = self.positional[:len(self.positional) - self.defaults]\n        missing = [p for i, p in enumerate(required)\n                   if i >= n_positional and (i < self.positional_only or p not in keywords)]\n        missing += [k for k in self.keyword_required if k not in keywords]\n        if missing:\n            out.append(f\"requires {', '.join(missing)}, which the call does not pass\")\n        accepted = set(self.positional[self.positional_only:]) | set(self.keyword_only)\n        unknown = [k for k in keywords if k not in accepted]\n        if unknown and not self.varkw:\n            out.append(f\"has no parameter named {', '.join(unknown)}\")\n        return out\n\n\n@dataclass(frozen=True)\nclass Definition:\n    name: str               # pkg.mod.Class.method: stable across moves and edits\n    kind: str               # function | method | class | constant\n    path: str\n    line: int\n    end_line: int\n    signature: str = \"\"     # callables: parameters and return type; classes: bases\n    body: str = \"\"          # hash of the body's syntax tree\n    value: str = \"\"         # constants: the value's source\n    params: Params | None = None     # callables: what a call must pass\n\n    @property\n    def short(self) -> str:\n        return self.name.rsplit(\".\", 1)[-1]\n\n\ndef _hash(*parts: str) -> str:\n    return hashlib.sha1(\"\\x00\".join(parts).encode(\"utf-8\")).hexdigest()[:12]\n\n\ndef _without_docstring(body: list[ast.stmt]) -> list[ast.stmt]:\n    if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) \\\n            and isinstance(body[0].value.value, str):\n        return body[1:]\n    return body\n\n\ndef _dump(nodes: list[ast.AST]) -> str:\n    return \"\\n\".join(ast.dump(n, include_attributes=False) for n in nodes)\n\n\ndef _signature(fn: ast.FunctionDef | ast.AsyncFunctionDef) -> str:\n    sig = f\"({ast.unparse(fn.args)})\"\n    if fn.returns is not None:\n        sig += f\" -> {ast.unparse(fn.returns)}\"\n    return (\"async \" if isinstance(fn, ast.AsyncFunctionDef) else \"\") + sig\n\n\ndef _params(fn, kind: str) -> Params:\n    a = fn.args\n    decorators = {d.id if isinstance(d, ast.Name) else getattr(d, \"attr\", \"\")\n                  for d in fn.decorator_list}\n    kw_required = tuple(arg.arg for arg, default in zip(a.kwonlyargs, a.kw_defaults)\n                        if default is None)\n    return Params(\n        positional=tuple(arg.arg for arg in a.posonlyargs + a.args),\n        defaults=len(a.defaults), positional_only=len(a.posonlyargs),\n        varargs=a.vararg is not None, keyword_only=tuple(arg.arg for arg in a.kwonlyargs),\n        keyword_required=kw_required, varkw=a.kwarg is not None,\n        binds_first=kind == \"method\" and \"staticmethod\" not in decorators)\n\n\ndef _function(fn, qual: str, kind: str, path: str) -> Definition:\n    return Definition(\n        name=qual, kind=kind, path=path, line=fn.lineno, end_line=fn.end_lineno or fn.lineno,\n        signature=_signature(fn),\n        body=_hash(_dump(fn.decorator_list), _dump(_without_docstring(fn.body))),\n        params=_params(fn, kind))\n\n\ndef _constants(stmt: ast.stmt, prefix: str, path: str) -> list[Definition]:\n    \"\"\"``NAME = value`` / ``NAME: T = value`` at module or class level.\"\"\"\n    if isinstance(stmt, ast.Assign):\n        targets, value = stmt.targets, stmt.value\n    elif isinstance(stmt, ast.AnnAssign) and stmt.value is not None:\n        targets, value = [stmt.target], stmt.value\n    else:\n        return []\n    text = ast.unparse(value)\n    return [Definition(name=f\"{prefix}.{t.id}\", kind=\"constant\", path=path, line=stmt.lineno,\n                       end_line=stmt.end_lineno or stmt.lineno, body=_hash(text), value=text)\n            for t in targets if isinstance(t, ast.Name)]\n\n\ndef _class(cls: ast.ClassDef, qual: str, path: str) -> list[Definition]:\n    members = [s for s in cls.body if not isinstance(s, (ast.FunctionDef, ast.AsyncFunctionDef))]\n    out = [Definition(\n        name=qual, kind=\"class\", path=path, line=cls.lineno, end_line=cls.end_lineno or cls.lineno,\n        signature=\", \".join(ast.unparse(b) for b in cls.bases),\n        body=_hash(_dump(cls.decorator_list), _dump(_without_docstring(members))))]\n    for stmt in cls.body:\n        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            out.append(_function(stmt, f\"{qual}.{stmt.name}\", \"method\", path))\n        elif isinstance(stmt, ast.ClassDef):\n            out += _class(stmt, f\"{qual}.{stmt.name}\", path)\n        else:\n            out += _constants(stmt, qual, path)\n    return out\n\n\ndef definitions_in(tree: ast.Module, path: str) -> list[Definition]:\n    mod = module_name(path)\n    out: list[Definition] = []\n    for stmt in tree.body:\n        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            out.append(_function(stmt, f\"{mod}.{stmt.name}\", \"function\", path))\n        elif isinstance(stmt, ast.ClassDef):\n            out += _class(stmt, f\"{mod}.{stmt.name}\", path)\n        else:\n            out += _constants(stmt, mod, path)\n    return out\n\n\ndef definitions(snapshot: Snapshot) -> dict[str, Definition]:\n    \"\"\"``{name: Definition}`` for the whole snapshot. A name defined twice keeps the last.\"\"\"\n    out: dict[str, Definition] = {}\n    for path in sorted(snapshot.files):\n        tree = snapshot.tree(path)\n        if tree is not None:\n            for d in definitions_in(tree, path):\n                out[d.name] = d\n    return out\n", "magellan_lite/diff.py": "\"\"\"What changed between two maps, and which lines of the new version that covers.\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections import defaultdict\nfrom dataclasses import dataclass\n\nfrom magellan_lite.defs import Definition\n\n#: how much each kind of change can do to the code that depends on it, worst first\nKINDS = (\"removed\", \"renamed\", \"signature\", \"value\", \"body\", \"added\")\n\n\n@dataclass\nclass Change:\n    kind: str                       # one of KINDS\n    name: str\n    path: str\n    line: int\n    before: Definition | None = None\n    after: Definition | None = None\n\n    @property\n    def detail(self) -> str:\n        if self.kind == \"signature\":\n            return f\"{self.before.signature}  ->  {self.after.signature}\"\n        if self.kind == \"value\":\n            return f\"{self.before.value}  ->  {self.after.value}\"\n        # one branch at a time: a removed change has no `after`, an added one no `before`\n        if self.kind == \"removed\":\n            return f\"{self.before.kind} deleted\"\n        if self.kind == \"added\":\n            return f\"new {self.after.kind}\"\n        if self.kind == \"renamed\":\n            return f\"renamed from {self.before.name}\"\n        return f\"{self.after.kind} body changed\"\n\n    def to_dict(self) -> dict:\n        return {\"kind\": self.kind, \"name\": self.name, \"path\": self.path, \"line\": self.line,\n                \"detail\": self.detail}\n\n\ndef diff(before: dict[str, Definition], after: dict[str, Definition]) -> list[Change]:\n    \"\"\"Every definition added, removed, renamed or edited. One change per definition: the worst.\"\"\"\n    out: list[Change] = []\n    for name in sorted(set(before) | set(after)):\n        b, a = before.get(name), after.get(name)\n        if a is None:\n            out.append(Change(\"removed\", name, b.path, b.line, before=b))\n        elif b is None:\n            out.append(Change(\"added\", name, a.path, a.line, after=a))\n        elif a.signature != b.signature:\n            out.append(Change(\"signature\", name, a.path, a.line, before=b, after=a))\n        elif a.kind == \"constant\" and a.value != b.value:\n            out.append(Change(\"value\", name, a.path, a.line, before=b, after=a))\n        elif a.body != b.body:\n            out.append(Change(\"body\", name, a.path, a.line, before=b, after=a))\n    out = _pair_renames(out)\n    out.sort(key=lambda c: (KINDS.index(c.kind), c.path, c.line))\n    return out\n\n\ndef _pair_renames(changes: list[Change]) -> list[Change]:\n    \"\"\"A function, method or class deleted under one name and added under another with the\n    same signature and body is one rename (or a move to another module), not two changes.\n\n    Pairs only when the match is unique. Constants are never paired: the same value under a\n    new name can be a new meaning -- Knight Capital's reused flag looked exactly like that.\n    \"\"\"\n    def key(d: Definition) -> tuple:\n        return d.kind, d.signature, d.body\n\n    removed: dict[tuple, list[Change]] = defaultdict(list)\n    added: dict[tuple, list[Change]] = defaultdict(list)\n    for c in changes:\n        if c.kind == \"removed\" and c.before.kind != \"constant\":\n            removed[key(c.before)].append(c)\n        elif c.kind == \"added\" and c.after.kind != \"constant\":\n            added[key(c.after)].append(c)\n    paired: set[int] = set()\n    renames: list[Change] = []\n    for k, gone in removed.items():\n        new = added.get(k, [])\n        if len(gone) == 1 and len(new) == 1:\n            old, now = gone[0], new[0]\n            renames.append(Change(\"renamed\", now.name, now.path, now.line,\n                                  before=old.before, after=now.after))\n            paired |= {id(old), id(now)}\n    return [c for c in changes if id(c) not in paired] + renames\n\n\nSpans = dict[str, list[tuple[int, int]]]\n\n\ndef changed_spans(changes: list[Change]) -> Spans:\n    \"\"\"``{path: [(first line, last line)]}`` of every definition the change added or edited.\n\n    A class whose own body is unchanged but whose method changed contributes only the method:\n    findings belong to the narrowest thing that changed.\n    \"\"\"\n    out: Spans = {}\n    for c in changes:\n        if c.after is not None:\n            out.setdefault(c.after.path, []).append((c.after.line, c.after.end_line))\n    return {p: sorted(set(s)) for p, s in out.items()}\n\n\ndef in_spans(spans: Spans, path: str, line: int) -> bool:\n    return any(start <= line <= end for start, end in spans.get(path, ()))\n", "magellan_lite/engine.py": "\"\"\"One check: map both versions, diff them, run the checklist on what the change touched.\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nfrom magellan_lite.defs import Definition, definitions\nfrom magellan_lite.diff import Change, Spans, changed_spans, diff, in_spans\nfrom magellan_lite.findings import Finding, iter_change_rules, run_file_rules\nfrom magellan_lite.graph import CallGraph, build_graph\nfrom magellan_lite.radius import blast_radius\nfrom magellan_lite.report import Report\nfrom magellan_lite.source import Snapshot, working_tree\n\n\n@dataclass\nclass ChangeContext:\n    \"\"\"Everything a ``@change_rule`` can look at.\"\"\"\n    root: Path\n    before: Snapshot\n    after: Snapshot\n    before_defs: dict[str, Definition]\n    after_defs: dict[str, Definition]\n    changes: list[Change]\n    spans: Spans\n    graph: CallGraph            # the new version's call graph (edges to deleted names kept)\n\n\ndef load_before(root: Path, against: str) -> Snapshot:\n    \"\"\"``git:REV`` (``git:`` alone means HEAD), or a directory holding the old version.\"\"\"\n    if against.startswith(\"git:\"):\n        from magellan_lite.git import snapshot_at   # only here: the website's copy has no git\n        return snapshot_at(root, against[4:] or \"HEAD\")\n    old = Path(against)\n    if old.is_dir():\n        return working_tree(old)\n    raise ValueError(f\"--against must be git:REV or a directory, not {against!r}\")\n\n\ndef check(root: str | Path = \".\", against: str = \"git:HEAD\") -> Report:\n    \"\"\"Compare a project on disk with a baseline (``git:REV`` or a directory).\"\"\"\n    root = Path(root).resolve()\n    return check_snapshots(load_before(root, against), working_tree(root), root, against)\n\n\ndef check_files(before: dict[str, str], after: dict[str, str]) -> Report:\n    \"\"\"Compare two versions given as ``{relative path: source}``: no disk, no git.\n    What the local server uses for code pasted into the website.\"\"\"\n    return check_snapshots(Snapshot(dict(before), \"before\"), Snapshot(dict(after), \"after\"),\n                           Path(\".\"), \"request\")\n\n\ndef check_snapshots(before: Snapshot, after: Snapshot, root: Path, against: str) -> Report:\n    import magellan_lite.rules  # noqa: F401  importing the package registers every rule\n\n    before_defs, after_defs = definitions(before), definitions(after)\n    changes = diff(before_defs, after_defs)\n    spans = changed_spans(changes)\n    report = Report(root=root.as_posix(), against=against, changes=changes)\n\n    for path in sorted(spans):\n        tree = after.tree(path)\n        if tree is None:\n            continue\n        found, errors = run_file_rules(tree, path)\n        report.findings += [f for f in found if in_spans(spans, path, f.line)]\n        report.errors += errors\n\n    # TODO(qol): inline suppressions. A finding whose line (or the line above) carries\n    #   `# magellan: ignore[rule-id]` is dropped here and counted instead (\"1 suppressed\").\n    #   Done when: tests/test_engine.py has a case where the comment silences exactly one rule.\n\n    # the blast radius: what the change reaches that it did not touch (radius.py)\n    graph = build_graph(after, after_defs, before_defs)\n    report.affected = blast_radius(changes, graph, after_defs)\n\n    ctx = ChangeContext(root, before, after, before_defs, after_defs, changes, spans, graph)\n    for r in iter_change_rules():\n        try:\n            report.findings += [f if f.fix or not r.fix else _with_fix(f, r.fix)\n                                for f in r.check(ctx)]\n        except Exception as exc:                    # noqa: BLE001 - reported, not hidden\n            report.errors.append(f\"rule {r.id} failed: {type(exc).__name__}: {exc}\")\n\n    report.errors += sorted(after.errors.values())\n    report.findings.sort(key=lambda f: (f.rank, f.path, f.line, f.rule))\n    return report\n\n\ndef _with_fix(f: Finding, fix: str) -> Finding:\n    f.fix = fix\n    return f\n", "magellan_lite/findings.py": "\"\"\"Findings and the rule registry. This is the shared contract: change it together.\n\nThere are two kinds of rule.\n\n``@rule`` looks at one parsed file and yields ``(where, message)`` or\n``(where, message, detail)``, where ``where`` is an AST node or a line number. The engine\nkeeps only what lands inside code the change touched, so a rule never needs to know about\nthe change::\n\n    @rule(\"debug-leftover\", \"low\", fix=\"Remove it before committing.\")\n    def debug_leftover(tree, path):\n        for node in ast.walk(tree):\n            if isinstance(node, ast.Call) and getattr(node.func, \"id\", \"\") == \"breakpoint\":\n                yield node, \"breakpoint() left in\"\n\n``@change_rule`` sees the whole change -- both versions of every definition -- and returns\n``Finding`` objects itself. Use it for rules about what changed *between* versions, such as\na constant's value handed to a new meaning.\n\n``blocking=True`` lets a rule's high or critical findings make the verdict ``block``. Keep it\nfor rules that mean \"this change will break something\", not \"have a look\".\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nfrom dataclasses import asdict, dataclass\nfrom typing import Callable, Iterable\n\nSEVERITIES = (\"critical\", \"high\", \"medium\", \"low\")\n\n\n@dataclass\nclass Finding:\n    rule: str\n    severity: str\n    message: str            # one line: what is wrong, where\n    path: str               # relative to the project root, forward slashes on every OS\n    line: int\n    detail: str = \"\"        # why it matters\n    fix: str = \"\"           # what to do about it\n\n    @property\n    def rank(self) -> int:\n        \"\"\"0 for critical, 3 for low: sort by it to put the worst first.\"\"\"\n        return SEVERITIES.index(self.severity)\n\n    def to_dict(self) -> dict:\n        return asdict(self)\n\n\n@dataclass(frozen=True)\nclass Rule:\n    id: str\n    severity: str\n    fix: str\n    blocking: bool\n    per_file: bool          # True: @rule (one file at a time); False: @change_rule\n    check: Callable\n\n\nRULES: dict[str, Rule] = {}\n\n\ndef _register(rule_id: str, severity: str, fix: str, blocking: bool, per_file: bool):\n    if severity not in SEVERITIES:\n        raise ValueError(f\"{rule_id}: severity must be one of {SEVERITIES}, not {severity!r}\")\n\n    def register(check: Callable) -> Callable:\n        if rule_id in RULES and RULES[rule_id].check is not check:\n            raise ValueError(f\"two rules are called {rule_id!r}\")\n        RULES[rule_id] = Rule(rule_id, severity, fix, blocking, per_file, check)\n        return check\n    return register\n\n\ndef rule(rule_id: str, severity: str, fix: str = \"\", blocking: bool = False):\n    \"\"\"Register a check over one parsed file. See the module docstring.\"\"\"\n    return _register(rule_id, severity, fix, blocking, per_file=True)\n\n\ndef change_rule(rule_id: str, severity: str, fix: str = \"\", blocking: bool = False):\n    \"\"\"Register a check over the whole change. See the module docstring.\"\"\"\n    return _register(rule_id, severity, fix, blocking, per_file=False)\n\n\ndef run_file_rules(tree: ast.Module, path: str) -> tuple[list[Finding], list[str]]:\n    \"\"\"Every per-file rule's findings for one file, and the errors of rules that crashed.\n\n    A broken rule must not take the whole check down: its error is reported instead.\n    \"\"\"\n    out: list[Finding] = []\n    errors: list[str] = []\n    for r in RULES.values():\n        if not r.per_file:\n            continue\n        try:\n            for hit in r.check(tree, path):\n                where, message, *rest = hit\n                line = where if isinstance(where, int) else getattr(where, \"lineno\", 0)\n                out.append(Finding(r.id, r.severity, message, path, line,\n                                   detail=rest[0] if rest else \"\", fix=r.fix))\n        except Exception as exc:                    # noqa: BLE001 - reported, not hidden\n            errors.append(f\"rule {r.id} failed on {path}: {type(exc).__name__}: {exc}\")\n    return out, errors\n\n\ndef blocking_rules() -> set[str]:\n    return {r.id for r in RULES.values() if r.blocking}\n\n\ndef iter_change_rules() -> Iterable[Rule]:\n    return [r for r in RULES.values() if not r.per_file]\n", "magellan_lite/graph.py": "\"\"\"The call graph: which definition calls, constructs or reads which.\n\nBuilt from syntax trees alone; nothing is imported or run. A call is resolved by name:\n\n- ``f()``: a function in the same module, or one imported (``from a.b import f``);\n- ``mod.f()``: after ``import mod`` (or ``import a.b as mod``);\n- ``self.m()`` / ``cls.m()``: a method of the class the call is in;\n- ``Ledger.post(...)``, ``Ledger(...)``: a class of this module and its methods.\n\nA method call on anything else (``order.update()``) cannot be resolved without types. When\nexactly one method in the project has that name, it is linked as a *guess*, which the blast\nradius weighs less; otherwise it is left out. Edges to definitions the change deleted are kept\n(``dangling``), so code still calling them can be found.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nfrom collections import defaultdict\nfrom dataclasses import dataclass\n\nfrom magellan_lite.defs import Definition\nfrom magellan_lite.source import Snapshot, module_name\n\n#: method names too common to guess at: `d.get()` is almost never the project's `get`\n_NO_GUESS = frozenset({\n    \"get\", \"set\", \"add\", \"append\", \"extend\", \"insert\", \"pop\", \"remove\", \"clear\", \"copy\",\n    \"update\", \"items\", \"keys\", \"values\", \"join\", \"split\", \"strip\", \"format\", \"replace\",\n    \"read\", \"write\", \"close\", \"open\", \"run\", \"send\", \"start\", \"stop\", \"sort\",\n    \"count\", \"index\", \"find\", \"encode\", \"decode\", \"lower\", \"upper\", \"startswith\",\n    \"endswith\", \"match\", \"search\", \"sub\", \"load\", \"dump\", \"loads\", \"dumps\",\n})\n\n\n@dataclass(frozen=True)\nclass Edge:\n    src: str                       # the definition that calls or reads\n    dst: str                       # what it calls or reads\n    kind: str                      # \"calls\" | \"reads\"\n    path: str\n    line: int\n    guess: bool = False            # matched by method name alone\n    bound: bool = False            # obj.method(...): `self` is passed for you\n    positional: int = 0            # positional arguments at the call site\n    keywords: tuple[str, ...] = ()\n    unpacked: bool = False         # *args or **kwargs at the call site: the count is unknown\n\n\n@dataclass(frozen=True)\nclass ImportSite:\n    path: str\n    line: int\n    target: str                    # the dotted name an import statement binds\n\n\nclass CallGraph:\n    def __init__(self, edges: list[Edge], imports: list[ImportSite]) -> None:\n        self.edges = edges\n        self.imports = imports\n        self._in: dict[str, list[Edge]] = defaultdict(list)\n        self._out: dict[str, list[Edge]] = defaultdict(list)\n        for e in edges:\n            self._in[e.dst].append(e)\n            self._out[e.src].append(e)\n\n    def callers(self, name: str) -> list[Edge]:\n        \"\"\"Edges into ``name``: who calls or reads it.\"\"\"\n        return self._in.get(name, [])\n\n    def uses(self, name: str) -> list[Edge]:\n        \"\"\"Edges out of ``name``: what it calls or reads.\"\"\"\n        return self._out.get(name, [])\n\n\ndef build_graph(snapshot: Snapshot, defs: dict[str, Definition],\n                old_defs: dict[str, Definition] | None = None) -> CallGraph:\n    \"\"\"The graph of ``snapshot``. ``old_defs`` (the previous version's map) keeps edges to\n    definitions that no longer exist, so the code still using them can be reported.\"\"\"\n    # what each name is, in either version: a read of a deleted constant still counts\n    kinds = {n: d.kind for n, d in (old_defs or {}).items()}\n    kinds.update({n: d.kind for n, d in defs.items()})\n    known = set(kinds)\n    methods: dict[str, list[str]] = defaultdict(list)\n    for d in defs.values():\n        if d.kind == \"method\":\n            methods[d.short].append(d.name)\n\n    edges: list[Edge] = []\n    import_sites: list[ImportSite] = []\n    for path in sorted(snapshot.files):\n        tree = snapshot.tree(path)\n        if tree is None:\n            continue\n        mod = module_name(path)\n        package = mod if path.endswith(\"__init__.py\") else mod.rpartition(\".\")[0]\n        table, sites = _imports(tree, package, path)\n        import_sites += sites\n        for owner, fn, cls in _callables(tree, mod):\n            edges += _Resolver(owner, fn, cls, mod, path, table, kinds, methods).edges()\n    return CallGraph(edges, import_sites)\n\n\ndef _imports(tree: ast.Module, package: str, path: str) -> tuple[dict[str, str], list[ImportSite]]:\n    \"\"\"``{bound name: dotted target}`` for every import in the module, and where each is.\"\"\"\n    table: dict[str, str] = {}\n    sites: list[ImportSite] = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Import):\n            for a in node.names:\n                if a.asname:\n                    table[a.asname] = a.name\n                else:\n                    top = a.name.split(\".\")[0]\n                    table[top] = top\n        elif isinstance(node, ast.ImportFrom):\n            base = node.module or \"\"\n            if node.level:                              # relative: from . / .. / .mod import\n                parts = package.split(\".\") if package else []\n                if node.level > 1:\n                    parts = parts[:len(parts) - (node.level - 1)]\n                base = \".\".join(parts + ([node.module] if node.module else []))\n            for a in node.names:\n                if a.name == \"*\":\n                    continue\n                target = f\"{base}.{a.name}\" if base else a.name\n                table[a.asname or a.name] = target\n                sites.append(ImportSite(path, node.lineno, target))\n    return table, sites\n\n\ndef _callables(tree: ast.Module, mod: str):\n    \"\"\"``(definition name, function node, enclosing class name or None)``, named as the map\n    names them (defs.py).\"\"\"\n    def visit(body, prefix, cls):\n        for stmt in body:\n            if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):\n                yield f\"{prefix}.{stmt.name}\", stmt, cls\n            elif isinstance(stmt, ast.ClassDef):\n                qual = f\"{prefix}.{stmt.name}\"\n                yield from visit(stmt.body, qual, qual)\n    yield from visit(tree.body, mod, None)\n\n\nclass _Resolver:\n    \"\"\"The edges out of one function.\"\"\"\n\n    def __init__(self, owner, fn, cls, mod, path, imports, kinds, methods) -> None:\n        self.owner, self.fn, self.cls, self.mod, self.path = owner, fn, cls, mod, path\n        self.imports, self.kinds, self.methods = imports, kinds, methods\n        self.known = kinds.keys()\n        self.locals = self._local_names(fn)\n\n    @staticmethod\n    def _local_names(fn) -> set[str]:\n        \"\"\"Parameters and names assigned in the function: a call to one of them is a call to\n        whatever was passed in, not to a module-level definition of the same name.\"\"\"\n        a = fn.args\n        names = {arg.arg for arg in a.posonlyargs + a.args + a.kwonlyargs}\n        names |= {x.arg for x in (a.vararg, a.kwarg) if x is not None}\n        for node in ast.walk(fn):\n            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):\n                names.add(node.id)\n            elif isinstance(node, ast.ExceptHandler) and node.name:\n                names.add(node.name)\n        return names\n\n    def _name(self, ident: str) -> str | None:\n        \"\"\"The definition a bare name refers to, if it is one of ours.\"\"\"\n        if ident in self.locals:\n            return None\n        if ident in self.imports and self.imports[ident] in self.known:\n            return self.imports[ident]\n        here = f\"{self.mod}.{ident}\"\n        return here if here in self.known else None\n\n    def _attribute(self, node: ast.Attribute) -> tuple[str | None, bool, bool]:\n        \"\"\"``(target, bound, guess)`` for ``X.attr``.\"\"\"\n        attr = node.attr\n        if isinstance(node.value, ast.Name):\n            base = node.value.id\n            if base in (\"self\", \"cls\") and self.cls:\n                target = f\"{self.cls}.{attr}\"\n                if target in self.known:\n                    return target, True, False\n            elif base not in self.locals:\n                if base in self.imports:\n                    target = f\"{self.imports[base]}.{attr}\"\n                    if target in self.known:\n                        return target, False, False\n                target = f\"{self.mod}.{base}.{attr}\"     # a class of this module\n                if target in self.known:\n                    return target, False, False\n        candidates = self.methods.get(attr, [])\n        if len(candidates) == 1 and attr not in _NO_GUESS:\n            return candidates[0], True, True\n        return None, False, False\n\n    def edges(self) -> list[Edge]:\n        out: list[Edge] = []\n        for node in ast.walk(self.fn):\n            if isinstance(node, ast.Call):\n                if isinstance(node.func, ast.Name):\n                    target, bound, guess = self._name(node.func.id), False, False\n                elif isinstance(node.func, ast.Attribute):\n                    target, bound, guess = self._attribute(node.func)\n                else:\n                    continue\n                if target and target != self.owner:\n                    out.append(Edge(\n                        self.owner, target, \"calls\", self.path, node.lineno, guess, bound,\n                        positional=sum(not isinstance(a, ast.Starred) for a in node.args),\n                        keywords=tuple(k.arg for k in node.keywords if k.arg),\n                        unpacked=any(isinstance(a, ast.Starred) for a in node.args)\n                        or any(k.arg is None for k in node.keywords)))\n            elif isinstance(node, (ast.Name, ast.Attribute)) and isinstance(node.ctx, ast.Load):\n                if isinstance(node, ast.Name):\n                    target = self._name(node.id)\n                else:\n                    target, _bound, guess = self._attribute(node)\n                    target = None if guess else target       # never guess at a read\n                if target and target != self.owner and self.kinds.get(target) == \"constant\":\n                    out.append(Edge(self.owner, target, \"reads\", self.path, node.lineno))\n        return out\n", "magellan_lite/output.py": "\"\"\"How a report reads in a terminal. JSON is ``Report.to_dict``.\"\"\"\n\nfrom __future__ import annotations\n\nfrom magellan_lite.report import Report\n\n_KIND = {\"removed\": \"del\", \"renamed\": \"ren\", \"signature\": \"sig\", \"value\": \"val\", \"body\": \"body\",\n         \"added\": \"new\"}\n\n\ndef _count(n: int, word: str) -> str:\n    return f\"{n} {word}{'' if n == 1 else 's'}\"\n\n\ndef text(report: Report, max_changes: int = 12, max_affected: int = 10) -> str:\n    lines = [f\"magellan-lite: {report.verdict.upper()} \u00b7 {_count(len(report.findings), 'finding')}\"\n             f\" \u00b7 {_count(len(report.changes), 'change')} in \"\n             f\"{_count(len(report.files_changed), 'file')} (against {report.against})\"]\n\n    if report.changes:\n        lines += [\"\", \"  changes\"]\n        width = max(len(c.name) for c in report.changes[:max_changes])\n        for c in report.changes[:max_changes]:\n            lines.append(f\"    {_KIND[c.kind]:>4}  {c.name:<{width}}  {c.path}:{c.line}\")\n        if len(report.changes) > max_changes:\n            lines.append(f\"    ... and {len(report.changes) - max_changes} more\")\n\n    if report.affected:\n        lines += [\"\", f\"  reaches {_count(len(report.affected), 'definition')} the change \"\n                      f\"did not touch (score fades with distance)\"]\n        width = max(len(a[\"name\"]) for a in report.affected[:max_affected])\n        for i, a in enumerate(report.affected[:max_affected]):\n            lines.append(f\"    {a['score']:.2f}  {_count(a['hops'], 'hop'):<7} \"\n                         f\"{a['name']:<{width}}  {a['path']}:{a['line']}\")\n            if i < 3:\n                lines.append(f\"          because {a['why']}\")\n        if len(report.affected) > max_affected:\n            lines.append(f\"    ... and {len(report.affected) - max_affected} more\")\n\n    lines += [\"\", \"  checklist\"]\n    if not report.findings:\n        lines.append(\"    nothing to check in what this change touched\")\n    for f in report.findings:\n        lines.append(f\"    [ ] {f.severity.upper():<8} {f.rule}  {f.path}:{f.line}\")\n        lines.append(f\"        {f.message}\")\n        if f.detail:\n            lines.append(f\"        {f.detail}\")\n        if f.fix:\n            lines.append(f\"        fix: {f.fix}\")\n\n    if report.errors:\n        lines += [\"\", \"  not checked\"]\n        lines += [f\"    {e}\" for e in report.errors]\n    return \"\\n\".join(lines)\n", "magellan_lite/radius.py": "\"\"\"The blast radius: code the change did not touch that it can still break, ranked.\n\nImpact travels *against* the call graph. If ``parse_record`` changes, the code that calls it\nis at risk; then whatever calls that code, and so on. Each change starts with a weight for how\nmuch it can do to the code that depends on it, and every hop multiplies the weight down, so a\nchain of direct calls stays hot while a long or uncertain chain fades out:\n\n    deleted or renamed 1.0   signature 0.95   value 0.8   body 0.6     (the seed)\n    a call 0.9   reading a constant 0.85   a guessed call x0.5         (each hop)\n\nA definition is listed with the best score any path gives it; propagation stops below\n``THRESHOLD`` or after ``MAX_HOPS``. Definitions the change edited are not listed: they are\nalready in the change.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom magellan_lite.defs import Definition\nfrom magellan_lite.diff import Change\nfrom magellan_lite.graph import CallGraph, Edge\n\nSEED = {\"removed\": 1.0, \"renamed\": 1.0, \"signature\": 0.95, \"value\": 0.8, \"body\": 0.6}\nSTEP = {\"calls\": 0.9, \"reads\": 0.85}\nGUESS = 0.5\nTHRESHOLD = 0.1\nMAX_HOPS = 6\n\n\ndef blast_radius(changes: list[Change], graph: CallGraph,\n                 defs: dict[str, Definition]) -> list[dict]:\n    \"\"\"The affected definitions, worst first: ``{name, path, line, hops, score, why}``.\"\"\"\n    changed = {c.name for c in changes} | {c.before.name for c in changes if c.before}\n    frontier: list[tuple[float, int, str]] = []\n    for c in changes:\n        seed = SEED.get(c.kind)\n        if seed is None:\n            continue\n        frontier.append((seed, 0, c.name))\n        if c.kind == \"renamed\":                     # callers of the old name are hit too\n            frontier.append((seed, 0, c.before.name))\n\n    best: dict[str, tuple[float, int, Edge]] = {}\n    while frontier:\n        score, hops, name = frontier.pop()\n        if hops >= MAX_HOPS:\n            continue\n        for e in graph.callers(name):\n            s = score * STEP[e.kind] * (GUESS if e.guess else 1.0)\n            if s < THRESHOLD or e.src in changed:\n                continue\n            if e.src not in best or s > best[e.src][0] + 1e-9:\n                best[e.src] = (s, hops + 1, e)\n                frontier.append((s, hops + 1, e.src))\n\n    out = []\n    for name, (score, hops, e) in best.items():\n        d = defs.get(name)\n        out.append({\n            \"name\": name, \"path\": d.path if d else e.path, \"line\": d.line if d else e.line,\n            \"hops\": hops, \"score\": round(score, 2),\n            \"why\": (f\"{e.src} {e.kind} {e.dst} ({e.path}:{e.line})\"\n                    + (\" -- a guess\" if e.guess else \"\")),\n        })\n    out.sort(key=lambda a: (-a[\"score\"], a[\"hops\"], a[\"name\"]))\n    return out\n", "magellan_lite/report.py": "\"\"\"What one check produces: the changes, the checklist, and a verdict. Shared contract.\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\n\nfrom magellan_lite.diff import Change\nfrom magellan_lite.findings import Finding, blocking_rules\n\nVERDICTS = (\"ok\", \"review\", \"block\")\n\n\n@dataclass\nclass Report:\n    root: str\n    against: str\n    changes: list[Change] = field(default_factory=list)\n    findings: list[Finding] = field(default_factory=list)\n    #: the blast radius: unedited code the change can break -- the engine's next step\n    affected: list[dict] = field(default_factory=list)\n    #: files that did not parse, rules that crashed: reported, never hidden\n    errors: list[str] = field(default_factory=list)\n\n    @property\n    def verdict(self) -> str:\n        \"\"\"``block``: a blocking rule found something high or worse. ``review``: something\n        medium or worse. ``ok``: nothing that needs a person.\"\"\"\n        blocking = blocking_rules()\n        if any(f.rule in blocking and f.severity in (\"critical\", \"high\") for f in self.findings):\n            return \"block\"\n        if any(f.severity in (\"critical\", \"high\", \"medium\") for f in self.findings):\n            return \"review\"\n        return \"ok\"\n\n    @property\n    def files_changed(self) -> list[str]:\n        return sorted({c.path for c in self.changes})\n\n    def fails(self, fail_on: str) -> bool:\n        \"\"\"Should this report stop a commit? ``fail_on`` is a verdict, or ``never``.\"\"\"\n        if fail_on == \"never\":\n            return False\n        return VERDICTS.index(self.verdict) >= VERDICTS.index(fail_on)\n\n    # TODO(qol): a PR comment bot. A workflow in .github/workflows/ that runs\n    #   `magellan-lite check --against git:origin/main --format json` on every pull request and\n    #   posts the verdict and checklist as a comment (actions/github-script). The most visible\n    #   thing for the least code. Done when a test PR with a mutable default gets a comment.\n\n    def to_dict(self) -> dict:\n        return {\n            \"verdict\": self.verdict,\n            \"root\": self.root,\n            \"against\": self.against,\n            \"files_changed\": self.files_changed,\n            \"changes\": [c.to_dict() for c in self.changes],\n            \"findings\": [f.to_dict() for f in self.findings],\n            \"affected\": self.affected,\n            \"errors\": self.errors,\n        }\n", "magellan_lite/rules/__init__.py": "\"\"\"The checklist. Importing this package registers every rule.\n\nAdd a rule: write it in its own module here (one rule, or a few related ones, per file),\nthen import that module below. Give it a test in ``tests/rules/``.\n\"\"\"\n\nfrom magellan_lite.rules import defaults  # noqa: F401\n\n# Calls the change breaks (signature-break, removed-still-referenced): need the call graph.\nfrom magellan_lite.rules import breaks  # noqa: F401\n\n# Starter rules: each file has numbered steps and a test waiting for it. A file whose\n# `@rule(...)` line is still commented out registers nothing, so these imports are safe.\nfrom magellan_lite.rules import assert_tuple, bare_except, compare_none, debug_leftover  # noqa: F401,E501\n\n# TODO(starter): new to this? Start with the four files imported above, in this order:\n#   bare_except.py -> assert_tuple.py -> compare_none.py -> debug_leftover.py\n#   Each one says exactly what to do, and its test tells you when you're done.\n\n# TODO(checklist): the rules that catch famous failures. Each one turns an incident in\n#   demo/incidents/ green: `python demo/run.py` shows which are still waiting.\n#\n#   1. leap-day-date (high, blocking): `date(d.year + 1, d.month, d.day)` and\n#      `d.replace(year=d.year + 1)` raise ValueError on February 29. Quiet when the offset is\n#      a multiple of 4, inside `try/except ValueError`, or when the function checks `== 29`.\n#      Turns azure-leap-day-2012 green. The easiest of these four: start here.\n#   2. reused-value (high): a @change_rule. A constant deleted (or given a new value) while a\n#      new constant in the same module takes its old value, and a function that read the old\n#      one now reads the new one AND calls different things. A plain rename calls the same\n#      things: stay quiet. Turns knight-capital-2012 step 3 green.\n#   3. loop-without-progress (high, blocking): a `while` loop whose body never changes what\n#      its condition reads, never passes it to a call, and never breaks/returns/raises.\n#      Skip `while True` and conditions that call things (polling). Turns knight-capital-2012\n#      step 2 green; the path-by-path version (Zune, `days == 366`) is the stretch goal.\n#   4. regex-catastrophic-backtracking (high): a changed regex literal with nested\n#      quantifiers like `(a+)+` or three overlapping unbounded parts like `.*(?:.*=.*)`.\n#      Parse with `re._parser` (3.11+) / `sre_parse` (3.10), never run the regex.\n#      Turns cloudflare-waf-2019 green.\n#   Stretch: unsynchronized-shared-state (therac-25-1986) needs thread analysis: last.\n#   When one lands, run `python demo/build_site.py` and commit site/data/: the website's\n#   story for that incident turns from \"rule in progress\" to caught (the tests remind you).\n#\n#   The full Magellan has tested versions of 1-4 (magellan/python/rules/, magellan/rules/):\n#   read them for the edge cases, then write your own small version here.\n", "magellan_lite/rules/assert_tuple.py": "\"\"\"assert-on-tuple: `assert (x, \"message\")` -- an assert that can never fail.\n\nWhy it matters: the parentheses turn the condition and the message into one tuple, and a\ntuple with something in it is always true. The assert passes even when x is False, so the\ncheck you meant to have is not there. (Python 3.8+ warns about it, but only when it runs.)\nThe intended code is `assert x, \"message\"` -- no parentheses.\n\"\"\"\n\nimport ast\n\nfrom magellan_lite.findings import rule  # noqa: F401\n\n\n@rule(\"assert-on-tuple\", \"medium\", fix='Drop the parentheses: `assert x, \"message\"`.')\ndef assert_on_tuple(tree: ast.Module, path: str):\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Assert) and isinstance(node.test, ast.Tuple) and node.test.elts:\n            yield node, \"This assert checks a tuple, which is always true\"\n", "magellan_lite/rules/bare_except.py": "\"\"\"bare-except: an `except:` with no exception type.\n\nWhy it matters: a bare `except:` also catches KeyboardInterrupt and SystemExit, so Ctrl+C\nstops working, and any real error inside the `try` disappears without a trace.\n\"\"\"\n\nimport ast\n\nfrom magellan_lite.findings import rule  # noqa: F401\n\n\n@rule(\"bare-except\", \"low\", fix=\"Catch what you expect, e.g. `except ValueError:`.\")\ndef bare_except(tree: ast.Module, path: str):\n    for node in ast.walk(tree):\n        if isinstance(node, ast.ExceptHandler) and node.type is None:\n            yield node, \"a bare `except:` also catches Ctrl+C and SystemExit\"\n\n\n", "magellan_lite/rules/breaks.py": "\"\"\"Calls the change breaks: a signature they no longer fit, or a definition that is gone.\n\nThese need the whole picture -- the old and new version of what changed, and the call graph\nof who uses it -- so they are change rules. Both block a commit: each one is a TypeError,\nNameError or ImportError waiting for the code path to run.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom magellan_lite.findings import Finding, change_rule\n\n\n@change_rule(\"signature-break\", \"critical\", blocking=True,\n             fix=\"Update the call, or give the new parameter a default so existing calls \"\n                 \"keep working.\")\ndef signature_break(ctx):\n    \"\"\"A call that fit the old signature and does not fit the new one.\"\"\"\n    edited = {c.name for c in ctx.changes}\n    seen = set()\n    for c in ctx.changes:\n        if c.kind != \"signature\" or not (c.before.params and c.after.params):\n            continue\n        for e in ctx.graph.callers(c.name):\n            if e.kind != \"calls\" or e.unpacked or e.guess or (e.path, e.line) in seen:\n                continue\n            new = c.after.params.bound() if e.bound else c.after.params\n            old = c.before.params.bound() if e.bound else c.before.params\n            now = new.problems(e.positional, e.keywords)\n            if not now or old.problems(e.positional, e.keywords):\n                continue                        # fits the new one, or never fit the old one\n            seen.add((e.path, e.line))\n            untouched = (\"It is in code this change did not touch, so nobody updated it: \"\n                         if e.src not in edited else \"\")\n            yield Finding(\n                \"signature-break\", \"critical\",\n                f\"{e.src} calls {c.after.short}() the old way: it now {now[0]}\",\n                e.path, e.line,\n                detail=(f\"{c.name} went from {c.before.signature} to {c.after.signature}. \"\n                        f\"{untouched}the call raises TypeError when it runs.\"))\n\n\n@change_rule(\"removed-still-referenced\", \"critical\", blocking=True,\n             fix=\"Restore it, or update the code that still uses it in the same change.\")\ndef removed_still_referenced(ctx):\n    \"\"\"Code that still calls, reads or imports something the change deleted or renamed.\"\"\"\n    seen = set()\n    for c in ctx.changes:\n        if c.kind not in (\"removed\", \"renamed\"):\n            continue\n        gone = c.before.name\n        if gone in ctx.after_defs:\n            continue\n        what = (f\"which this change renamed to {c.after.name}\" if c.kind == \"renamed\"\n                else \"which this change deleted\")\n        uses = [(e.path, e.line, f\"{e.src} still {e.kind} {gone}\") for e in ctx.graph.callers(gone)]\n        uses += [(i.path, i.line, f\"{i.path} still imports {gone}\")\n                 for i in ctx.graph.imports if i.target == gone]\n        for path, line, message in uses:\n            if (path, line) in seen:\n                continue\n            seen.add((path, line))\n            yield Finding(\n                \"removed-still-referenced\", \"critical\", f\"{message}, {what}\", path, line,\n                detail=\"It fails when that line runs: NameError or AttributeError for a call \"\n                       \"or read, ImportError as soon as the module is imported.\")\n", "magellan_lite/rules/compare_none.py": "\"\"\"compare-to-none: `x == None` or `x != None` instead of `x is None`.\n\nWhy it matters: `==` asks the object whether it equals None, and a class can answer\nanything (numpy arrays and some ORM columns do). `is None` always means what it says.\n\"\"\"\n\nimport ast\n\nfrom magellan_lite.findings import rule  # noqa: F401\n\n\n@rule(\"compare-to-none\", \"low\", fix=\"Use `is None` / `is not None`.\")\ndef compare_to_none(tree: ast.Module, path: str):\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Compare):\n            for op, right in zip(node.ops, node.comparators):\n                if isinstance(op, (ast.Eq, ast.NotEq)) and isinstance(right, ast.Constant) and right.value is None:\n                    yield node, \"compare with None using `is` / `is not`, not `==` / `!=`\"\n\n", "magellan_lite/rules/debug_leftover.py": "\"\"\"debug-leftover: print(), breakpoint() and pdb.set_trace() left in changed code.\n\nWhy it matters: a stray breakpoint() hangs a server waiting for a debugger nobody attached;\na stray print() fills logs or corrupts output another program reads.\n\"\"\"\n\nimport ast\n\nfrom magellan_lite.findings import rule  # noqa: F401\n\n\n@rule(\"debug-leftover\", \"low\", fix=\"Remove it before committing (use logging for output).\")\ndef debug_leftover(tree: ast.Module, path: str):\n    # 1. where print() is fine: inside `if __name__ == \"__main__\":` blocks\n    main_blocks = []\n    for node in ast.walk(tree):\n        if (isinstance(node, ast.If) and isinstance(node.test, ast.Compare)\n                and isinstance(node.test.left, ast.Name) and node.test.left.id == \"__name__\"):\n            main_blocks.append((node.lineno, node.end_lineno))\n\n    # 2. every call: is it one of the debugging leftovers?\n    for node in ast.walk(tree):\n        if not isinstance(node, ast.Call):\n            continue                      # not a call: skip to the next node\n        func = node.func\n        if isinstance(func, ast.Name) and func.id == \"breakpoint\":\n            yield node, \"breakpoint() left in\"\n        elif isinstance(func, ast.Name) and func.id == \"print\":\n            if not any(start <= node.lineno <= end for start, end in main_blocks):\n                yield node, \"print() left in\"\n        elif (isinstance(func, ast.Attribute) and func.attr == \"set_trace\"\n              and isinstance(func.value, ast.Name) and func.value.id in (\"pdb\", \"ipdb\")):\n            yield node, \"pdb.set_trace() left in\"\n\n", "magellan_lite/rules/defaults.py": "\"\"\"Mutable default arguments: the example rule. Copy its shape for a new one.\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\n\nfrom magellan_lite.findings import rule\n\n_MUTABLE_CALLS = {\"list\", \"dict\", \"set\", \"bytearray\", \"defaultdict\", \"deque\", \"OrderedDict\"}\n\n\ndef _is_mutable(node: ast.expr) -> bool:\n    if isinstance(node, (ast.List, ast.Dict, ast.Set, ast.ListComp, ast.DictComp, ast.SetComp)):\n        return True\n    if isinstance(node, ast.Call):\n        name = node.func.id if isinstance(node.func, ast.Name) else \\\n            node.func.attr if isinstance(node.func, ast.Attribute) else \"\"\n        return name in _MUTABLE_CALLS\n    return False\n\n\n@rule(\"mutable-default-argument\", \"medium\",\n      fix=\"Default to None and build the container inside the function.\")\ndef mutable_default_argument(tree: ast.Module, path: str):\n    for fn in ast.walk(tree):\n        if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):\n            continue\n        defaults = fn.args.defaults + [d for d in fn.args.kw_defaults if d is not None]\n        for d in defaults:\n            if _is_mutable(d):\n                name = getattr(fn, \"name\", \"lambda\")\n                yield (d, f\"{name}() has a mutable default argument `{ast.unparse(d)}`\",\n                       \"It is created once, when the function is defined, and every call \"\n                       \"that leaves the argument out shares it: state leaks between calls.\")\n", "magellan_lite/source.py": "\"\"\"Reading a project: which files, their text, their syntax trees.\n\nLessons from running the full Magellan on Windows are built in: files are read as UTF-8\nwhatever the system locale, paths use forward slashes on every OS, and line endings never\ncount as a change (definitions are hashed from syntax trees, not text).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport ast\nimport os\nfrom pathlib import Path\n\n#: directories that hold no project code (tools, environments, build output)\nSKIP_DIRS = frozenset({\"__pycache__\", \"venv\", \"env\", \"build\", \"dist\", \"node_modules\",\n                       \"site-packages\"})\n\n\ndef is_skipped_dir(name: str) -> bool:\n    return name in SKIP_DIRS or name.startswith(\".\")\n\n\ndef iter_python_files(root: Path) -> list[str]:\n    \"\"\"Every ``.py`` file under ``root``, as sorted forward-slash paths relative to it.\"\"\"\n    out: list[str] = []\n    for dirpath, dirnames, filenames in os.walk(root):\n        dirnames[:] = sorted(d for d in dirnames if not is_skipped_dir(d))\n        for name in sorted(filenames):\n            if name.endswith(\".py\"):\n                out.append(Path(dirpath, name).relative_to(root).as_posix())\n    return out\n\n\ndef decode(data: bytes) -> str:\n    \"\"\"Source bytes as text: UTF-8 (a BOM is dropped), never the system's code page.\"\"\"\n    return data.decode(\"utf-8-sig\", errors=\"replace\")\n\n\ndef module_name(path: str) -> str:\n    \"\"\"``pkg/mod.py`` -> ``pkg.mod``; ``pkg/__init__.py`` -> ``pkg``; ``src/`` is dropped.\"\"\"\n    parts = path[:-3].split(\"/\") if path.endswith(\".py\") else path.split(\"/\")\n    if parts and parts[0] == \"src\" and len(parts) > 1:\n        parts = parts[1:]\n    if parts and parts[-1] == \"__init__\":\n        parts = parts[:-1]\n    return \".\".join(parts) or \"__init__\"\n\n\nclass Snapshot:\n    \"\"\"One version of a project: ``{relative path: source text}``, parsed on demand.\"\"\"\n\n    def __init__(self, files: dict[str, str], label: str = \"\") -> None:\n        self.files = files\n        self.label = label\n        self.errors: dict[str, str] = {}\n        self._trees: dict[str, ast.Module | None] = {}\n\n    def tree(self, path: str) -> ast.Module | None:\n        \"\"\"The file's syntax tree, or None when it does not parse (the error is kept).\"\"\"\n        if path not in self._trees:\n            try:\n                self._trees[path] = ast.parse(self.files[path], filename=path)\n            except SyntaxError as exc:\n                self._trees[path] = None\n                self.errors[path] = f\"{path}:{exc.lineno or 0}: {exc.msg}\"\n        return self._trees[path]\n\n\ndef working_tree(root: str | Path) -> Snapshot:\n    \"\"\"The project as it is on disk now.\"\"\"\n    root = Path(root)\n    files = {rel: decode((root / rel).read_bytes()) for rel in iter_python_files(root)}\n    return Snapshot(files, label=str(root))\n", "magellan_lite/web.py": "\"\"\"What the website draws for one change: the report, plus the map it was worked out on.\n\nThe local server's ``/api/check``, the website's \"Try it\" box (which runs this module in the\nvisitor's browser, through Pyodide) and ``demo/build_site.py`` all call ``check_with_map``, so\nthe page draws the same thing whichever of them answered.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom magellan_lite.defs import Definition, definitions\nfrom magellan_lite.engine import check_snapshots\nfrom magellan_lite.graph import build_graph\nfrom magellan_lite.source import Snapshot, module_name\n\n#: past this many definitions the map keeps only the change's neighbourhood\nMAX_NODES = 60\n\n\ndef check_with_map(before: dict[str, str], after: dict[str, str]) -> dict:\n    \"\"\"``Report.to_dict()`` for two versions given as ``{path: source}``, plus ``map``.\"\"\"\n    b, a = Snapshot(dict(before), \"before\"), Snapshot(dict(after), \"after\")\n    report = check_snapshots(b, a, Path(\".\"), \"request\").to_dict()\n    report[\"map\"] = code_map(b, a, report)\n    return report\n\n\ndef code_map(before: Snapshot, after: Snapshot, report: dict) -> dict:\n    \"\"\"The definitions of the new version (and the ones the change deleted) and who calls or\n    reads whom, each marked with what the change did to it: ``{\"nodes\": [...], \"edges\": [...]}``.\n    \"\"\"\n    before_defs, after_defs = definitions(before), definitions(after)\n    graph = build_graph(after, after_defs, before_defs)\n\n    changed = {c[\"name\"]: c[\"kind\"] for c in report[\"changes\"]}\n    affected = {a[\"name\"]: a for a in report[\"affected\"]}\n    defs: dict[str, tuple[Definition, bool]] = {n: (d, False) for n, d in after_defs.items()}\n    defs.update({n: (d, True) for n, d in before_defs.items() if n not in after_defs})\n\n    edges, seen = [], set()\n    for e in graph.edges:\n        key = (e.src, e.dst, e.kind)\n        if e.src in defs and e.dst in defs and e.src != e.dst and key not in seen:\n            seen.add(key)\n            edges.append({\"src\": e.src, \"dst\": e.dst, \"kind\": e.kind, \"guess\": e.guess})\n\n    keep = set(defs)\n    if len(keep) > MAX_NODES:                   # the change, what it reaches, their neighbours\n        core = set(changed) | set(affected) | {n for n, (d, _) in defs.items()\n                                              if _has_finding(d, report[\"findings\"])}\n        near = {e[\"src\"] for e in edges if e[\"dst\"] in core} | \\\n               {e[\"dst\"] for e in edges if e[\"src\"] in core}\n        keep = set(sorted(core)[:MAX_NODES])\n        keep |= set(sorted(near - keep)[:max(0, MAX_NODES - len(keep))])\n        edges = [e for e in edges if e[\"src\"] in keep and e[\"dst\"] in keep]\n\n    nodes = []\n    for name in sorted(keep):\n        d, removed = defs[name]\n        mod = module_name(d.path)\n        hit = affected.get(name)\n        nodes.append({\n            \"id\": name,\n            \"label\": name[len(mod) + 1:] if name.startswith(mod + \".\") else name,\n            \"path\": d.path, \"line\": d.line, \"kind\": d.kind,\n            \"change\": changed.get(name, \"\"),\n            \"removed\": removed,\n            \"score\": hit[\"score\"] if hit else 0,\n            \"hops\": hit[\"hops\"] if hit else 0,\n            \"finding\": not removed and _has_finding(d, report[\"findings\"]),\n        })\n    return {\"nodes\": nodes, \"edges\": edges}\n\n\ndef _has_finding(d: Definition, findings: list[dict]) -> bool:\n    return any(f[\"path\"] == d.path and d.line <= f[\"line\"] <= d.end_line and d.kind != \"class\"\n               for f in findings)\n"}};
